import { useQuery } from '@tanstack/react-query';
import { lineItemsKey, fetchLineItems, type LineItem } from './queries';
import { formatMoney } from '../../ui/money';

// An invoice's line items plus the derived total. Queries for itself under ['lineitems', invoiceId]
// — never handed its data by a parent (CLAUDE.md rule 5). Each line's amount is qty * unitPrice; the
// invoice total is a client-side aggregate of the same rows, so it stays in step with them for free
// ("work out the total for me"). Carries the stable data-testid contract the test reads.
export function LineItemsTable({ invoiceId }: { invoiceId: number }) {
  const { data: lineItems } = useQuery({
    queryKey: lineItemsKey(invoiceId),
    queryFn: () => fetchLineItems(invoiceId),
  });

  if (!lineItems) {
    return null;
  }

  const total = lineItems.reduce(
    (sum, line) => sum + Number(line.qty) * Number(line.unitPrice),
    0,
  );

  return (
    <>
      <table data-testid="invoice-lineitems-table">
        <thead>
          <tr>
            <th>Description</th>
            <th>Qty</th>
            <th>Unit price</th>
            <th>Amount</th>
          </tr>
        </thead>
        <tbody>
          {lineItems.map((line: LineItem) => (
            <tr key={line.id} data-testid={`lineitem-row-${line.id}`}>
              <td data-testid="lineitem-description">{line.description}</td>
              <td data-testid="lineitem-qty">{line.qty}</td>
              <td data-testid="lineitem-unitprice">{formatMoney(line.unitPrice)}</td>
              <td data-testid="lineitem-amount">
                {formatMoney(Number(line.qty) * Number(line.unitPrice))}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <p data-testid="invoice-amount">{formatMoney(total)}</p>
    </>
  );
}
import { getJson, postJson } from '../../api/http';

// An invoice's line items under a per-invoice key: anything showing invoice 1's lines reads
// ['lineitems', 1], and a write invalidates the same key to refresh them (CLAUDE.md rule 5). A line
// carries what is being charged for (description), how many (qty) and the price each (unitPrice).
export type LineItem = {
  id: number;
  invoiceId: number;
  description: string;
  qty: number;
  unitPrice: number;
};

export const lineItemsKey = (invoiceId: number) => ['lineitems', invoiceId] as const;

export function fetchLineItems(invoiceId: number): Promise<LineItem[]> {
  return getJson<LineItem[]>(`/api/invoices/${invoiceId}/lineitems`);
}

/** Add a line to an invoice; the invoice id is in the path, the rest is the body (CLAUDE.md server). */
export function createLineItem(
  invoiceId: number,
  input: { description: string; qty: number; unitPrice: number },
): Promise<LineItem> {
  return postJson<LineItem>(`/api/invoices/${invoiceId}/lineitems`, input);
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { lineItemsKey, createLineItem } from './queries';

// Add a line to an invoice: a description, how many, and the price each. useState holds only what the
// user is currently entering (CLAUDE.md rule 4); the write is a mutation that invalidates
// ['lineitems', invoiceId] so the list and its derived total refresh themselves (rule 5). Carries
// the stable data-testid contract the test reads.
export function LineItemForm({ invoiceId }: { invoiceId: number }) {
  const [description, setDescription] = useState('');
  const [qty, setQty] = useState('');
  const [unitPrice, setUnitPrice] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();

  const mutation = useMutation({
    mutationFn: (input: { description: string; qty: number; unitPrice: number }) =>
      createLineItem(invoiceId, input),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: lineItemsKey(invoiceId) });
      setDescription('');
      setQty('');
      setUnitPrice('');
    },
  });

  return (
    <form
      data-testid="lineitem-form"
      onSubmit={(event) => {
        event.preventDefault();
        const quantity = Number(qty);
        const price = Number(unitPrice);
        if (
          description.trim() === '' ||
          !Number.isInteger(quantity) ||
          quantity <= 0 ||
          Number.isNaN(price) ||
          price <= 0
        ) {
          setError('Enter a description, a whole quantity and a price above zero.');
          return;
        }
        setError('');
        mutation.mutate({ description: description.trim(), qty: quantity, unitPrice: price });
      }}
    >
      <input
        data-testid="lineitem-form-description"
        placeholder="Description"
        value={description}
        onChange={(event) => setDescription(event.target.value)}
      />
      <input
        data-testid="lineitem-form-qty"
        placeholder="Qty"
        value={qty}
        onChange={(event) => setQty(event.target.value)}
      />
      <input
        data-testid="lineitem-form-unitprice"
        placeholder="Unit price"
        value={unitPrice}
        onChange={(event) => setUnitPrice(event.target.value)}
      />
      <button data-testid="lineitem-form-submit" type="submit">
        Add line item
      </button>
      {error !== '' && <p data-testid="lineitem-form-error">{error}</p>}
    </form>
  );
}

